<div class="page-header d-flex"><h2 class="page-title"><?= lang('products') ?></h2><div class="ms-auto"><a class="btn btn-primary" href="<?= site_url('products/create') ?>"><?= lang('add_product') ?></a></div></div><div class="card"><div class="table-responsive"><table class="table table-vcenter data-table" data-source="<?= site_url('products/data') ?>" data-fields="code,name,name_ar,category,price,status,action"><thead><tr><th><?= lang('code') ?></th><th><?= lang('name') ?></th><th><?= lang('arabic_name') ?></th><th><?= lang('category') ?></th><th><?= lang('price') ?></th><th><?= lang('status') ?></th><th></th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?= e($product['code']) ?></td><td><?= e($product['name']) ?></td><td><?= e($product['name_ar']) ?></td><td><?= e($product['category']) ?></td><td><?= sar($product['price']) ?></td><td><?= e(lang($product['status'])) ?></td><td><a class="btn btn-sm" href="<?= site_url('products/edit/' . $product['id']) ?>"><?= lang('edit') ?></a></td></tr><?php endforeach; ?></tbody></table></div></div>
